<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><div class="section-heading"><div><p class="eyebrow">KATALOG TOKO</p><h1>Kelola produk</h1><p class="text-muted mb-0"><?= $pager->getTotal() ?> produk dalam katalog.</p></div><a class="btn btn-primary" href="<?= site_url('admin/produk/tambah') ?>">+ Tambah Produk</a></div><div class="table-responsive admin-table" tabindex="0" role="region" aria-label="Daftar produk, geser untuk melihat semua kolom"><table class="table align-middle mb-0"><thead><tr><th scope="col">Produk</th><th scope="col">Kategori</th><th scope="col">Harga</th><th scope="col">Status</th><th scope="col">Tindakan</th></tr></thead><tbody><?php foreach ($products as $product): ?><tr><td><div class="table-product"><img src="<?= esc(product_image($product['gambar']), 'attr') ?>" width="56" height="64" alt="" loading="lazy"><strong><?= esc($product['nama_produk']) ?></strong></div></td><td><?= esc($product['kategori']) ?></td><td class="text-nowrap"><?= rupiah($product['harga']) ?></td><td><span class="status-pill"><?= $product['status_ketersediaan'] === 'tersedia' ? 'Tersedia' : 'Tidak tersedia' ?></span></td><td><div class="d-flex gap-2"><a class="btn btn-sm btn-outline-primary" href="<?= site_url('admin/produk/edit/' . $product['id']) ?>" aria-label="Edit <?= esc($product['nama_produk'], 'attr') ?>">Edit</a><form method="post" action="<?= site_url('admin/produk/hapus/' . $product['id']) ?>" data-delete-name="<?= esc($product['nama_produk'], 'attr') ?>"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger" type="submit" disabled data-delete-button aria-label="Hapus <?= esc($product['nama_produk'], 'attr') ?>">Hapus</button></form></div></td></tr><?php endforeach ?><?php if (! $products): ?><tr><td colspan="5" class="p-5 text-center">Belum ada produk. Tambahkan produk pertama Anda.</td></tr><?php endif ?></tbody></table></div><?= $pager->links('default', 'shop') ?><noscript><p class="alert alert-warning mt-3">Aktifkan JavaScript untuk konfirmasi sebelum menghapus produk.</p></noscript><?= $this->endSection() ?>
